					SlotPlan plain = reverse ? graph.right : graph.left;
					SlotPlan otherSelected = reverse ? graph.left : graph.right;
					assertThat(mixed ? ((FilterPlan) otherSelected).arg : otherSelected).isSameAs(plain);
					assertThat(LmdbNativeInteriorPlans.hasAlternatives(selected.plan)).isFalse();
